package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct { // 01 AMT-REC, 11 bytes
	ArAcct string // PIC X(4) @0 len=4
	ArAmt  decimal.Decimal // PIC 9(5)V99 @4 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsBigTotal decimal.Decimal = decimal.Zero // PIC 9(7)V99 len=9 = 0
var WsWrapTotal decimal.Decimal = decimal.Zero // PIC 9(5)V99 len=7 = 0
var WsSafeTotal decimal.Decimal = decimal.Zero // PIC 9(5)V99 len=7 = 0
var WsOverflows int64 = 0 // PIC 99 len=2 = 0
var WsCount int64 = 0 // PIC 99 len=2 = 0
var WsHalf decimal.Decimal = decimal.Zero // PIC 9(5)V9 len=6 = 0
var WsAmtEd string // PIC ZZ,ZZ9.99 len=9
var WsWrapEd string // PIC ZZ,ZZ9.99 len=9
var WsSafeEd string // PIC ZZ,ZZ9.99 len=9
var WsHalfEd string // PIC ZZ,ZZ9.9 len=8

var curRec AmtRec
var inputLines []string
var inputIdx int
var inputDone bool

func isInputDone() bool { return inputDone }

func parseAmt(s string) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	// keep only digits (DISPLAY numeric)
	t := ""
	for _, c := range s {
		if c >= '0' && c <= '9' {
			t += string(c)
		}
	}
	if t == "" {
		return decimal.Zero
	}
	var n int64
	fmt.Sscanf(t, "%d", &n)
	// PIC 9(5)V99 : last 2 digits are fractional; but field width is 7
	// Parse as integer then shift -2. If fewer digits, leading zeros implied.
	// Use decimal.New(n, -2)
	return decimal.New(n, -2)
}

func loadInput() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		inputLines = nil
		return
	}
	// Split on '\n', strip single trailing '\r', keep other spaces
	s := string(data)
	parts := strings.Split(s, "\n")
	// If file ends with newline, last part is "" after final \n -> drop it (not a record)
	if len(parts) > 0 && parts[len(parts)-1] == "" && len(s) > 0 && s[len(s)-1] == '\n' {
		parts = parts[:len(parts)-1]
	} else if len(parts) == 1 && parts[0] == "" {
		// empty file -> no records
		inputLines = nil
		return
	}
	for i, p := range parts {
		if strings.HasSuffix(p, "\r") {
			parts[i] = p[:len(p)-1]
		}
	}
	inputLines = parts
	inputIdx = 0
}

func makeRecord(line string) AmtRec {
	// pad with spaces on right to 11
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	} else if len(line) > 11 {
		line = line[:11]
	}
	acct := line[0:4]
	amtStr := line[4:11]
	return AmtRec{ArAcct: acct, ArAmt: parseAmt(amtStr)}
}

// format ZZ,ZZ9.99 (9 chars)
func formatZZZZ9_99(v decimal.Decimal) string {
	// truncate toward zero to 2 decimals (values already at 2)
	v = v.Truncate(2)
	neg := v.IsNegative()
	if neg {
		v = v.Neg()
	}
	cents := v.Shift(2).Truncate(0).IntPart()
	intPart := cents / 100
	frac := cents % 100
	if frac < 0 {
		frac = -frac
	}
	intPart = intPart % 100000
	s5 := fmt.Sprintf("%05d", intPart)
	d := []byte(s5) // 5 digits
	// suppression for first 4
	out := make([]byte, 9)
	// determine chars for d0..d4
	chars := make([]byte, 5)
	suppressed := true
	for i := 0; i < 4; i++ {
		if suppressed && d[i] == '0' {
			chars[i] = ' '
		} else {
			chars[i] = d[i]
			suppressed = false
		}
	}
	chars[4] = d[4]
	// check if any non-space before comma (d0,d1)
	commaSuppressed := (chars[0] == ' ' && chars[1] == ' ')
	out[0] = chars[0]
	out[1] = chars[1]
	if commaSuppressed {
		out[2] = ' '
	} else {
		out[2] = ','
	}
	out[3] = chars[2]
	out[4] = chars[3]
	out[5] = chars[4]
	out[6] = '.'
	out[7] = byte('0' + frac/10)
	out[8] = byte('0' + frac%10)
	_ = neg
	return string(out)
}

// format ZZ,ZZ9.9 (8 chars)
func formatZZZZ9_9(v decimal.Decimal) string {
	v = v.Truncate(1)
	neg := v.IsNegative()
	if neg {
		v = v.Neg()
	}
	tenths := v.Shift(1).Truncate(0).IntPart()
	intPart := tenths / 10
	frac := tenths % 10
	if frac < 0 {
		frac = -frac
	}
	intPart = intPart % 100000
	s5 := fmt.Sprintf("%05d", intPart)
	d := []byte(s5)
	chars := make([]byte, 5)
	suppressed := true
	for i := 0; i < 4; i++ {
		if suppressed && d[i] == '0' {
			chars[i] = ' '
		} else {
			chars[i] = d[i]
			suppressed = false
		}
	}
	chars[4] = d[4]
	commaSuppressed := (chars[0] == ' ' && chars[1] == ' ')
	out := make([]byte, 8)
	out[0] = chars[0]
	out[1] = chars[1]
	if commaSuppressed {
		out[2] = ' '
	} else {
		out[2] = ','
	}
	out[3] = chars[2]
	out[4] = chars[3]
	out[5] = chars[4]
	out[6] = '.'
	out[7] = byte('0' + frac)
	_ = neg
	return string(out)
}

func formatPIC99(v int64) string {
	v = v % 100
	if v < 0 {
		v += 100
	}
	return fmt.Sprintf("%02d", v)
}

func MainPara() {
	// OPEN INPUT AMT-FILE
	loadInput()
	inputDone = false
	WsEofFlag = "N"
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE AMT-FILE
	SummaryPara()
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	curRec = makeRecord(line)
}

func ProcessPara() {
	// ADD AR-AMT TO WS-BIG-TOTAL (PIC 9(7)V99, wrap on overflow)
	cand := WsBigTotal.Add(curRec.ArAmt).Truncate(2)
	// keep only low-order digits: modulo 10000000.00
	cents := cand.Shift(2).Truncate(0).IntPart()
	modCents := int64(10000000 * 100) // 1_000_000_000
	// positive modulo
	m := cents % modCents
	if m < 0 {
		m += modCents
	}
	// Rebuild only if overflow occurred (cents outside range); otherwise keep cand to preserve exactness
	// For positive values, m == cents when no overflow.
	if m != cents {
		WsBigTotal = decimal.New(m, -2)
	} else {
		WsBigTotal = cand
	}

	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL (drop high digits)
	bigCents := WsBigTotal.Shift(2).Truncate(0).IntPart()
	wrapMod := int64(100000 * 100) // 10_000_000
	wm := bigCents % wrapMod
	if wm < 0 {
		wm += wrapMod
	}
	WsWrapTotal = decimal.New(wm, -2)

	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA
	safeCand := WsSafeTotal.Add(curRec.ArAmt).Truncate(2)
	limit := decimal.New(9999999, -2) // 99999.99
	if safeCand.GreaterThan(limit) || safeCand.IsNegative() {
		// size error: target unchanged
		OverflowPara()
	} else {
		WsSafeTotal = safeCand
	}

	// ADD 1 TO WS-COUNT (PIC 99 wrap)
	WsCount = (WsCount + 1) % 100

	// COMPUTE WS-HALF = AR-AMT / 2 (truncated to 1 decimal)
	amtCents := curRec.ArAmt.Shift(2).Truncate(0).IntPart()
	// tenths truncated toward zero: cents/20
	var tenths int64
	if amtCents >= 0 {
		tenths = amtCents / 20
		rem := amtCents % 20
		_ = rem
	} else {
		// truncate toward zero
		tenths = -((-amtCents) / 20)
	}
	// store into PIC 9(5)V9 : drop high digits if needed (won't happen) then truncate already
	// apply modulo 1000000 tenths? integer part 5 digits + 1 decimal => modulo 100000*10 tenths
	tmod := int64(100000 * 10)
	tm := tenths % tmod
	WsHalf = decimal.New(tm, -1)

	WsAmtEd = formatZZZZ9_99(curRec.ArAmt)
	WsWrapEd = formatZZZZ9_99(WsWrapTotal)
	WsSafeEd = formatZZZZ9_99(WsSafeTotal)
	WsHalfEd = formatZZZZ9_9(WsHalf)
	fmt.Printf("%s %s %s %s %s\n", curRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	ReadPara()
}

func SummaryPara() {
	fmt.Printf("RECORDS: %s\n", formatPIC99(WsCount))
	fmt.Printf("OVERFLOWS: %s\n", formatPIC99(WsOverflows))
}

func OverflowPara() {
	WsOverflows = (WsOverflows + 1) % 100
}

func main() {
	MainPara()
}
